const isBengaluruHeroRecord=item=>item.id==='inscription-begur'||(item.evidenceKind==='candidate'&&bengaluruHeroStoneMatchers.some(matcher=>`${item.name?.en||''} ${item.place?.en||''} ${item.kmlFolder||''}`.toLowerCase().includes(matcher)))
